    @EventHandler
    public void handle( CreateRetentionScheduleEvent event) {
        entityManager.persist(new RetentionSchedule(event.getRetentionScheduleId(), event.getName(), event.getRetentionPeriodMonths(), event.getRepositories(), event.getRecords(), event.getExceptions(), event.getDispositionReviews(), event.getRetentionTrigger(), event.getDispositionAction(), event.getStatus()));
    }

